import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  contentHtml: string;
  source: string;
}

export function slugify(filename: string): string {
  const base = path.basename(filename, path.extname(filename));
  return base
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function parseMarkdown(content: string, source: string): Page {
  const { data, content: body } = matter(content);

  const slug = slugify(source);
  const title = typeof data.title === 'string' && data.title.trim()
    ? data.title
    : slug;

  let date: string | undefined;
  if (typeof data.date === 'string' && data.date.trim()) {
    date = data.date;
  } else if (data.date instanceof Date) {
    date = data.date.toISOString();
  }

  let tags: string[] = [];
  if (Array.isArray(data.tags)) {
    tags = data.tags.map((t) => String(t).trim()).filter(Boolean);
  } else if (typeof data.tags === 'string') {
    tags = data.tags.split(',').map((t) => t.trim()).filter(Boolean);
  }

  const contentHtml = marked.parse(body, { async: false }) as string;

  return { slug, title, date, tags, contentHtml, source };
}

export function readMarkdownFile(filePath: string): Page {
  const content = fs.readFileSync(filePath, 'utf8');
  return parseMarkdown(content, path.basename(filePath));
}

import type { Page } from './parse';

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatTags(tags: string[]): string {
  if (tags.length === 0) return '';
  const items = tags.map((t) => `<span class="tag">${escapeHtml(t)}</span>`).join(' ');
  return `<p class="tags">${items}</p>`;
}

function formatDate(date?: string): string {
  if (!date) return '';
  return `<p class="date"><time datetime="${escapeHtml(date)}">${escapeHtml(date)}</time></p>`;
}

export function renderPage(page: Page): string {
  const meta = formatDate(page.date) + formatTags(page.tags);
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <nav><a href="index.html">&larr; Home</a></nav>
  <article>
    <h1>${escapeHtml(page.title)}</h1>
    ${meta}
    ${page.contentHtml}
  </article>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => {
    const da = a.date ?? '';
    const db = b.date ?? '';
    return db.localeCompare(da);
  });

  const items = sorted
    .map((p) => {
      const date = p.date ? `<time datetime="${escapeHtml(p.date)}">${escapeHtml(p.date)}</time> ` : '';
      return `    <li><a href="${escapeHtml(p.slug)}.html">${escapeHtml(p.title)}</a> ${date}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Home</title>
</head>
<body>
  <header><h1>Home</h1></header>
  <main>
    <ul class="pages">
${items}
    </ul>
  </main>
</body>
</html>
`;
}

import fs from 'fs';
import path from 'path';
import type { Page } from './parse';
import { readMarkdownFile } from './parse';
import { renderIndex, renderPage } from './template';

export interface BuildResult {
  pages: Page[];
  filesWritten: string[];
}

function collectMarkdownFiles(dir: string): string[] {
  const files: string[] = [];
  if (!fs.existsSync(dir)) {
    return files;
  }
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...collectMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      files.push(full);
    }
  }
  return files;
}

export function buildSite(contentDir: string, outputDir: string): BuildResult {
  const files = collectMarkdownFiles(contentDir);
  const pages = files.map((f) => readMarkdownFile(f));
  pages.sort((a, b) => a.slug.localeCompare(b.slug));

  fs.mkdirSync(outputDir, { recursive: true });

  const filesWritten: string[] = [];

  for (const page of pages) {
    const filePath = path.join(outputDir, `${page.slug}.html`);
    fs.writeFileSync(filePath, renderPage(page), 'utf8');
    filesWritten.push(filePath);
  }

  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, renderIndex(pages), 'utf8');
  filesWritten.push(indexPath);

  return { pages, filesWritten };
}

#!/usr/bin/env node

import { buildSite } from './build';

const DEFAULT_CONTENT = './content';
const DEFAULT_OUTPUT = './dist';

export interface CliOptions {
  contentDir: string;
  outputDir: string;
}

export interface ParseArgsResult {
  command?: string;
  options: CliOptions;
  error?: string;
}

export function parseArgs(args: string[]): ParseArgsResult {
  const options: CliOptions = {
    contentDir: DEFAULT_CONTENT,
    outputDir: DEFAULT_OUTPUT,
  };

  const command = args.find((a) => a === 'build' || a === 'serve');

  let i = 0;
  while (i < args.length) {
    const arg = args[i];
    if (arg === '--content' || arg === '--output') {
      const value = args[i + 1];
      if (value === undefined) {
        return { command, options, error: `Missing value for ${arg}` };
      }
      if (arg === '--content') {
        options.contentDir = value;
      } else {
        options.outputDir = value;
      }
      i += 2;
    } else {
      i += 1;
    }
  }

  return { command, options };
}

export function run(args: string[]): void {
  const { command, options, error } = parseArgs(args);

  if (error) {
    console.error(`Error: ${error}`);
    process.exitCode = 1;
    return;
  }

  if (command !== 'build') {
    console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
    process.exitCode = 1;
    return;
  }

  const result = buildSite(options.contentDir, options.outputDir);
  console.log(`Built ${result.pages.length} page(s) into ${options.outputDir}`);
}

if (require.main === module) {
  run(process.argv.slice(2));
}

export { parseMarkdown, readMarkdownFile, slugify } from './parse';
export type { Page } from './parse';
export { buildSite } from './build';
export type { BuildResult } from './build';
export { renderPage, renderIndex, escapeHtml } from './template';
export { parseArgs, run } from './cli';
export type { CliOptions, ParseArgsResult } from './cli';

import fs from 'fs';
import os from 'os';
import path from 'path';
import { parseMarkdown, slugify } from '../parse';
import { buildSite } from '../build';
import { renderIndex, renderPage, escapeHtml } from '../template';

function makeTempDir(): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
}

describe('slugify', () => {
  it('lowercases and kebab-cases a filename', () => {
    expect(slugify('My First Post.md')).toBe('my-first-post');
  });

  it('strips the extension', () => {
    expect(slugify('about.markdown')).toBe('about');
  });

  it('handles slugs with numbers', () => {
    expect(slugify('part-1.md')).toBe('part-1');
  });
});

describe('parseMarkdown', () => {
  it('parses frontmatter title, date, and tags', () => {
    const page = parseMarkdown(
      `---
title: Hello World
date: 2024-01-15
tags: [intro, welcome]
---

# Heading

Some **bold** text.
`,
      'hello-world.md',
    );

    expect(page.title).toBe('Hello World');
    expect(page.date).toBe('2024-01-15');
    expect(page.tags).toEqual(['intro', 'welcome']);
    expect(page.slug).toBe('hello-world');
    expect(page.contentHtml).toContain('<h1>Heading</h1>');
    expect(page.contentHtml).toContain('<strong>bold</strong>');
  });

  it('parses comma-separated tags from a string', () => {
    const page = parseMarkdown(
      `---
title: Tags
tags: one, two, three
---

Body
`,
      'tags.md',
    );

    expect(page.tags).toEqual(['one', 'two', 'three']);
  });

  it('falls back to slug as title when frontmatter is missing', () => {
    const page = parseMarkdown('# Just a heading', 'no-title.md');
    expect(page.title).toBe('no-title');
    expect(page.tags).toEqual([]);
    expect(page.date).toBeUndefined();
    expect(page.contentHtml).toContain('<h1>Just a heading</h1>');
  });
});

describe('renderPage', () => {
  it('renders a full HTML document with escaped title', () => {
    const page = {
      slug: 'post',
      title: 'A <script> Title',
      date: '2024-01-01',
      tags: ['x'],
      contentHtml: '<p>Body</p>',
      source: 'post.md',
    };
    const html = renderPage(page);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('&lt;script&gt;');
    expect(html).toContain('<h1>A &lt;script&gt; Title</h1>');
    expect(html).toContain('<p>Body</p>');
    expect(html).toContain('index.html');
  });
});

describe('renderIndex', () => {
  it('lists pages with links sorted by date descending', () => {
    const pages = [
      {
        slug: 'old',
        title: 'Old',
        date: '2023-01-01',
        tags: [],
        contentHtml: '',
        source: 'old.md',
      },
      {
        slug: 'new',
        title: 'New',
        date: '2024-01-01',
        tags: [],
        contentHtml: '',
        source: 'new.md',
      },
    ];
    const html = renderIndex(pages);
    const newIndex = html.indexOf('new.html');
    const oldIndex = html.indexOf('old.html');
    expect(newIndex).toBeGreaterThan(-1);
    expect(oldIndex).toBeGreaterThan(-1);
    expect(newIndex).toBeLessThan(oldIndex);
  });
});

describe('escapeHtml', () => {
  it('escapes special characters', () => {
    expect(escapeHtml(`<a href="x">&'`)).toBe('&lt;a href=&quot;x&quot;&gt;&amp;&#39;');
  });
});

describe('buildSite', () => {
  it('generates index.html and one HTML file per page', () => {
    const contentDir = path.join(makeTempDir(), 'content');
    const outputDir = path.join(makeTempDir(), 'dist');
    fs.mkdirSync(contentDir, { recursive: true });

    fs.writeFileSync(
      path.join(contentDir, 'first.md'),
      `---
title: First
date: 2024-02-01
tags: [one]
---

# First post
`,
      'utf8',
    );
    fs.writeFileSync(
      path.join(contentDir, 'nested', 'second.md').split('/nested')[0].length > 0
        ? path.join(contentDir, 'second.md')
        : path.join(contentDir, 'second.md'),
      `---
title: Second
date: 2024-01-01
---

Second body
`,
      'utf8',
    );

    const result = buildSite(contentDir, outputDir);

    expect(result.pages).toHaveLength(2);
    expect(result.pages.map((p) => p.slug).sort()).toEqual(['first', 'second']);

    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second.html'))).toBe(true);

    const index = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(index).toContain('first.html');
    expect(index).toContain('second.html');
    expect(index).toContain('First');

    const page = fs.readFileSync(path.join(outputDir, 'first.html'), 'utf8');
    expect(page).toContain('<h1>First</h1>');
    expect(page).toContain('First post');
  });

  it('handles an empty content directory', () => {
    const contentDir = path.join(makeTempDir(), 'empty');
    const outputDir = path.join(makeTempDir(), 'dist');
    fs.mkdirSync(contentDir, { recursive: true });

    const result = buildSite(contentDir, outputDir);
    expect(result.pages).toHaveLength(0);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
  });
});

import { parseArgs } from '../cli';

describe('parseArgs', () => {
  it('parses the build command with defaults', () => {
    const result = parseArgs(['build']);
    expect(result.command).toBe('build');
    expect(result.options.contentDir).toBe('./content');
    expect(result.options.outputDir).toBe('./dist');
    expect(result.error).toBeUndefined();
  });

  it('parses --content and --output', () => {
    const result = parseArgs(['build', '--content', 'posts', '--output', 'public']);
    expect(result.command).toBe('build');
    expect(result.options.contentDir).toBe('posts');
    expect(result.options.outputDir).toBe('public');
  });

  it('handles options before the command', () => {
    const result = parseArgs(['--output', 'out', 'build']);
    expect(result.command).toBe('build');
    expect(result.options.outputDir).toBe('out');
  });

  it('returns an error when a value is missing', () => {
    const result = parseArgs(['build', '--content']);
    expect(result.error).toBe('Missing value for --content');
  });
});

